# Let me check if it's about whether the color fills the entire row/column for each section
# Or about which color has a MORE uniform/filled distribution

def check_filled_patterns(grid, h_line=4):
    """Check for colors that fill entire rows above and below"""
    above_filled = {"2": False, "4": False}
    below_filled = {"2": False, "4": False}

    # Check if color appears in ALL rows above and below in AT LEAST ONE column
    for color in [2, 4]:
        # Find columns where this color appears
        color_cols = set()
        for col in range(len(grid[0])):
            if any(color in row[col] for row in grid):
                color_cols.add(col)

        # Check above
        above_cols = set()
        for col in range(len(grid[0])):
            if any(color == row[col] for row in grid[:h_line]):
                above_cols.add(col)

        # Check if color has ANY column where it appears in ALL above rows
        has_above_full_col = any(color == row[col] for row in grid[:h_line] for col in above_cols)

        # Check below
        below_cols = set()
        for col in range(len(grid[0])):
            if any(color == row[col] for row in grid[h_line+1:]):
                below_cols.add(col)

        has_below_full_col = any(color == row[col] for row in grid[h_line+1:] for col in below_cols)

    print(f"Above full col: {has_above_full_col}")
    print(f"Below full col: {has_below_full_col}")

# Let me check row length of color clusters
def get_row_spans(grid, h_line=4, color=2):
    """For each section, find which rows a color appears in, and the span"""
    above_rows = set()
    above_cols = set()

    for row_idx, row in enumerate(grid[:h_line]):
        if color in row:
            above_rows.add(row_idx)
            # Add all cols where color appears in this row
            for col_idx, val in enumerate(row):
                if val == color:
                    above_cols.add(col_idx)

    below_rows = set()
    below_cols = set()

    for row_idx, row in enumerate(grid[h_line+1:]):
        below_rows.add(row_idx)
        for col_idx, val in enumerate(row):
            if val == color:
                below_cols.add(col_idx)

    return above_rows, above_cols, below_rows, below_cols

