def summarize(color_counts, preserve_order=False):
    if preserve_order:
        return {k: (v if v>0 else 0) for k, v in color_counts.items()}
    max_counts = {c: max(d2_above.get(c, 0), d2_below.get(c, 0)) for c in color_counts}
    min_counts = {c: min(d2_above.get(c, 0), d2_below.get(c, 0)) for c in color_counts}
    sum_counts = {c: sum(d2_above.get(c, 0), d2_below.get(c, 0)) for c in color_counts}
    return max_counts, min_counts, sum_counts

